import React, { useRef, useState, useEffect } from "react";
import "./VideoCarousel.css";

export default function VideoCarousel() {
  const videos = [
    "/assets/banner1.mp4",
    "/assets/banner2.mp4",
    "/assets/banner3.mp4",
    "/assets/banner4.mp4",
  ];

  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [fade, setFade] = useState(false);
  const vRef = useRef(null);

  // Toggle play/pause
  const togglePlay = () => {
    if (!vRef.current) return;
    if (playing) {
      vRef.current.pause();
    } else {
      vRef.current.play().catch(() => {});
    }
    setPlaying((p) => !p);
  };

  // Move to next video (with fade)
  const next = () => {
    setFade(true);
    setTimeout(() => {
      setIndex((i) => (i + 1) % videos.length);
      setFade(false);
    }, 500);
    setPlaying(false);
  };

  // Move to previous video (with fade)
  const prev = () => {
    setFade(true);
    setTimeout(() => {
      setIndex((i) => (i - 1 + videos.length) % videos.length);
      setFade(false);
    }, 500);
    setPlaying(false);
  };

  // 🔁 Auto slide every 6 seconds
  useEffect(() => {
    const timer = setInterval(() => {
      next();
    }, 6000);
    return () => clearInterval(timer);
  }, []);

  // Reset fade each time index changes
  useEffect(() => {
    setFade(false);
  }, [index]);

  return (
    <div className="video-banner-container">
      <div className={`fade-layer ${fade ? "fade-out" : "fade-in"}`}>
        <video
          key={videos[index]}
          ref={vRef}
          src={videos[index]}
          className="banner-video"
          muted
          playsInline
          controls={false}
          onClick={togglePlay}
        />
      </div>

      <button className="vc-btn prev" onClick={prev}>
        ⟨
      </button>
      <button className="vc-btn next" onClick={next}>
        ⟩
      </button>

      <button className="play-overlay" onClick={togglePlay}>
        {playing ? "❚❚" : "►"}
      </button>

      <div className="video-index">
        {index + 1}/{videos.length}
      </div>
    </div>
  );
}
